#include "sector_ai_model.hpp"
#include "sector_relation_review.hpp"
#include "sector_research_model.hpp"
#include "business_store.hpp"
#include "source_analysis_packet.hpp"
#include "research_runs_model.hpp"
#include "evidence_review_model.hpp"
#include <QUrl>
namespace sectorResearch {
QByteArray bytes(const QJsonValue& v){return v.isArray()?QJsonDocument(v.toArray()).toJson(QJsonDocument::Compact):QJsonDocument(v.toObject()).toJson(QJsonDocument::Compact);}
QString fingerprint(const QJsonValue& v){return researchRuns::fingerprint(v);}
QString scopeKey(const QJsonObject& s){return s.value("kind").toString()+":"+s.value("id").toString();}
QJsonObject scope(const QJsonObject& s){business::require(QStringList{"sector","industry"}.contains(s.value("kind").toString())&&!s.value("id").toString().trimmed().isEmpty()&&!s.value("name").toString().trimmed().isEmpty(),"需完整稳定主题身份和名称");business::require(bytes(s).size()<=sourceAnalysis::ByteLimit,"主题快照过大");return s;}
static QJsonObject seal(QJsonObject r){r["id"]=r.value("kind").toString()+":"+fingerprint(r);return r;}
QJsonObject packet(const QJsonObject& s,const QJsonArray& docs,const QString& manual,const QString& question){scope(s);for(auto v:docs){auto ref=v.toObject();auto snap=ref.value("snapshot").toObject();business::require(QStringList{"docs","collections"}.contains(ref.value("kind").toString())&&!ref.value("id").toString().isEmpty()&&ref.value("id")==snap.value("id")&&ref.value("bodyHash")==sourceAnalysis::hash(snap.value("text").toString()+QChar(0)+snap.value("originalText").toString()),"冻结来源身份/正文指纹无效");}business::require(!manual.trimmed().isEmpty()||!docs.isEmpty(),"请选择或填写材料");QString prompt="人工板块/产业研究交接。未执行在线AI。区分当日热度与月度持续性；月度缺失为未知，成员样本估计不可当指数事实。新闻为线索，需核验日期、原文、风险与反证；不推断成员、供应链归属或收入。\n主题完整快照：\n"+QString::fromUtf8(bytes(s))+"\n材料：\n"+manual+"\n本机来源：\n"+QString::fromUtf8(bytes(docs))+"\n问题：\n"+question;
return seal({{"kind","packets"},{"scope",s},{"documents",docs},{"manual",manual},{"question",question},{"prompt",prompt},{"verification","manual-unverified"}});}
QJsonObject result(const QJsonObject& p,const QString& input){validate(p);business::require(p.value("kind")=="packets"&&!input.trimmed().isEmpty(),"需冻结材料包和完整回填");QString text=input.trimmed();QJsonParseError error;auto doc=QJsonDocument::fromJson(input.toUtf8(),&error);QJsonArray candidates;QString proof="manual-no-returned-packet-proof";
if(error.error==QJsonParseError::NoError&&doc.isObject()&&doc.object().value("schema")=="sector-research-return-v1"){auto o=doc.object();business::require(o.value("packetId")==p.value("id")&&o.value("scopeId")==p.value("scope").toObject().value("id"),"返回材料包/主题身份不匹配");text=o.value("report").toString();business::require(o.value("candidates").isUndefined()||o.value("candidates").isArray(),"候选需数组");candidates=o.value("candidates").toArray();proof="returned-packet-id-matched-manual";}else{QString start="WEBSTOCK_HOT_MARKET_ANALYSIS_START",end="WEBSTOCK_HOT_MARKET_ANALYSIS_END";int a=text.indexOf(start),b=text.indexOf(end);if(a>=0){business::require(b>a&&!text.mid(b+end.size()).trimmed().size()&&text.left(a).trimmed().isEmpty(),"手工回填标记不完整或含额外内容");text=text.mid(a+start.size(),b-a-start.size()).trimmed();}}
business::require(!text.isEmpty(),"回填报告为空");return seal({{"kind","results"},{"packetId",p.value("id")},{"packetSnapshot",p},{"scope",p.value("scope")},{"raw",input},{"text",text},{"candidates",candidates},{"binding",proof},{"verification","manual-unverified"}});}
static void list(const QJsonObject& o,const QString& key,bool needed){business::require(!o.contains(key)||o.value(key).isArray(),key+"需数组");auto a=o.value(key).toArray();business::require(a.size()<=30&&(!needed||!a.isEmpty()),key+"缺失或超过30项");for(auto v:a){business::require(v.isString()&&!v.toString().trimmed().isEmpty(),key+"项无效");if(key=="evidenceRefs"){QUrl u(v.toString());business::require(u.isValid()&&QStringList{"http","https"}.contains(u.scheme())&&!u.host().isEmpty()&&u.userInfo().isEmpty(),"来源链接需公开HTTP地址");business::require(!QRegularExpression("(?:[?&])(token|password|api_key|access_token|secret)=",QRegularExpression::CaseInsensitiveOption).match(u.toString()).hasMatch(),"来源链接含凭据参数");}if(key=="relatedCodes")business::require(QRegularExpression("^[0-9]{6}$").match(v.toString()).hasMatch(),"代码无效；不猜测市场");}}
static QJsonObject artifact(const QJsonObject& o){QString schema=o.value("schema").toString();bool hot=schema=="webstock.market-hotspots/v1";business::require(hot||schema=="webstock.industry-chain-updates/v1","不支持的外部材料schema");auto payload=o.value("payload").toObject();QString key=hot?"items":"chains";business::require(payload.value(key).isArray(),"材料行需数组");auto rows=payload.value(key).toArray();business::require(!rows.isEmpty()&&rows.size()<=20,"材料需1至20行，未截断");for(auto v:rows){business::require(v.isObject(),"材料行格式无效");auto r=v.toObject();business::require(!r.value("name").toString().trimmed().isEmpty()&&!r.value("thesis").toString().trimmed().isEmpty(),"名称/逻辑缺失");list(r,"risks",true);list(r,"evidenceRefs",true);list(r,"relatedCodes",false);list(r,"drivers",false);if(!hot){list(r,"stages",true);list(r,"catalysts",false);}}
return seal({{"kind","artifacts"},{"original",o},{"rows",rows},{"verification","external-unverified"},{"association","unbound"}});}
static QJsonArray batch(const QJsonObject& o){for(auto key:o.keys())business::require(QStringList{"schema","source","revision","asOf","automaticTrading","artifacts","deliveries"}.contains(key),"批次未知顶层字段");business::require(o.value("automaticTrading").isBool()&&!o.value("automaticTrading").toBool(),"批次automaticTrading必须false");const auto source=o.value("source").toObject(),asOf=o.value("asOf").toObject();for(auto key:{"system","taskId","generatedAt"})business::require(!source.value(key).toString().trimmed().isEmpty(),"批次来源字段缺失");business::require(!source.value("runId").toString(source.value("scheduledFor").toString()).trimmed().isEmpty(),"批次runId缺失");double revision=o.value("revision").toDouble();business::require(revision>=1&&std::floor(revision)==revision,"批次revision无效");business::require(QDate::fromString(asOf.value("marketDate").toString(),Qt::ISODate).isValid()&&asOf.value("marketDate").toString().size()==10&&QDateTime::fromString(asOf.value("observedAt").toString(),Qt::ISODate).isValid()&&asOf.value("timezone")=="Asia/Shanghai","批次日期/时区无效");auto rows=o.value("artifacts").toArray();business::require(!rows.isEmpty()&&rows.size()<=3,"批次需1至3产物");QSet<QString> kinds;QJsonArray out;bool picks=false,thsEligible=false;for(auto v:rows){auto r=v.toObject();QString kind=r.value("kind").toString();business::require(!kinds.contains(kind),"批次同类产物重复");kinds.insert(kind);if(kind=="research-picks"){business::require(r.value("schema")=="webstock.research-picks/v1","候选schema无效");auto ps=r.value("payload").toObject().value("picks").toArray();business::require(!ps.isEmpty()&&ps.size()<=20,"批次候选需1至20行");QSet<QString> codes;QSet<int> ranks;for(int i=0;i<ps.size();++i){auto p=ps[i].toObject();QString code=p.value("code").toString();business::require(QRegularExpression("^(000|001|002|003|300|301|302|600|601|603|605|688|689|920)[0-9]{3}$").match(code).hasMatch()&&!codes.contains(code),"批次代码无效或重复");codes.insert(code);double rank=p.contains("rank")?p.value("rank").toDouble(-1):i+1;business::require(rank>=1&&rank<=20&&std::floor(rank)==rank&&!ranks.contains(int(rank)),"批次rank无效或重复");ranks.insert(int(rank));business::require(!p.value("name").toString().trimmed().isEmpty()&&!p.value("thesis").toString().trimmed().isEmpty(),"批次候选名称/逻辑缺失");list(p,"risks",true);list(p,"evidenceRefs",true);thsEligible=thsEligible||(p.value("includeInTonghuashun").isBool()&&p.value("includeInTonghuashun").toBool());}picks=true;}else{business::require(kind=="market-hotspots"||kind=="industry-chain-updates","批次产物类型无效");business::require(r.value("schema")==QString("webstock.")+kind+"/v1","产物kind/schema冲突");r["batchOriginal"]=o;out.append(artifact(r));}}business::require(picks&&!out.isEmpty(),"需含候选和热点/产业材料；不导入独立荐股");QSet<QString> targets;for(auto v:o.value("deliveries").toArray()){auto target=v.toObject().value("target").toString();business::require(QStringList{"webstock-research","tonghuashun-watchlist"}.contains(target)&&!targets.contains(target),"批次投递目标无效或重复");targets.insert(target);}business::require(targets.contains("webstock-research")&&(!targets.contains("tonghuashun-watchlist")||thsEligible),"批次投递声明无效");return out;}
QJsonArray decode(const QByteArray& b){business::require(b.size()<=sourceAnalysis::ByteLimit,"导入超过25MiB");QJsonParseError e;auto d=QJsonDocument::fromJson(b,&e);business::require(e.error==QJsonParseError::NoError&&d.isObject(),"需完整JSON对象");const auto o=d.object();if(o.value("schema")=="sector-research-v1"){business::require(o.value("records").isArray(),"备份records缺失");QJsonArray a;for(auto v:o.value("records").toArray()){business::require(v.isObject(),"记录需对象");a.append(validate(v.toObject()));}return a;}QJsonArray a;if(o.contains("hotspots")||o.contains("industryChains")){for(auto key:{"hotspots","industryChains"})if(!o.value(key).isNull()&&!o.value(key).isUndefined()){business::require(o.value(key).isObject(),"外部材料包装无效");a.append(artifact(o.value(key).toObject()));}business::require(!a.isEmpty(),"没有外部材料");return a;}if(o.value("schema")=="webstock.external-research-batch/v1")return batch(o);a.append(artifact(o));return a;}
QJsonObject review(const QJsonObject& source,int row,const QString& id,const QString& name,const QJsonArray& catalogue){validate(source);auto rows=source.value(source.value("kind")=="artifacts"?"rows":"candidates").toArray();business::require(row>=0&&row<rows.size(),"候选行不存在");auto raw=rows[row].toObject();QJsonObject input=raw;if(source.value("kind")=="artifacts"){business::require(raw.value("relatedCodes").toArray().contains(id.section(':',2,2)),"代码不在所选原材料行");input={{"code",id.section(':',2,2)},{"name",name},{"nameOrigin","manual-supplied"},{"original",raw}};}else{business::require(raw.value("name").toString()==name,"名称与候选原文不符");input["original"]=raw;}
auto audit=evidenceReview::audit(input,id,catalogue);business::require(audit.value("identityState")=="exact","完整身份及名称未与本机目录精确一致");return seal({{"kind","reviews"},{"sourceSnapshot",source},{"row",row},{"candidate",audit},{"catalogueSnapshot",catalogue},{"verification","manual-unverified"},{"acknowledged",true}});}
QJsonObject validate(QJsonObject r){if(r["kind"]=="relation-reviews")return sectorRelation::validateVersion(r);if(r["kind"]=="ai-reports")return sectorAi::validateRecord(r);business::require(bytes(r).size()<=sourceAnalysis::ByteLimit,"记录超过25MiB");auto original=r;r.remove("id");QString kind=r.value("kind").toString();QJsonObject expected;if(kind=="packets")expected=packet(r.value("scope").toObject(),r.value("documents").toArray(),r.value("manual").toString(),r.value("question").toString());else if(kind=="results")expected=result(r.value("packetSnapshot").toObject(),r.value("raw").toString());else if(kind=="artifacts")expected=artifact(r.value("original").toObject());else if(kind=="reviews"){auto c=r.value("candidate").toObject();expected=review(r.value("sourceSnapshot").toObject(),r.value("row").toInt(-1),c.value("instrumentId").toString(),c.value("name").toString(),r.value("catalogueSnapshot").toArray());}else if(kind=="associations"){scope(r.value("scope").toObject());business::require(r.value("acknowledged")==true,"关联需人工确认");validate(r.value("artifactSnapshot").toObject());expected=seal(r);}else business::require(false,"记录类型不支持；不导入草稿预览");business::require(original==expected,"记录原文/摘要/身份不一致");return original;}
QString read(const QJsonObject& r){return QString::fromUtf8(QJsonDocument(r).toJson(QJsonDocument::Indented));}
}

